using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InspectAttackHands{
 public static object Run(){var report=new List<object>();foreach(var live in GameObject.Find("New Knight Attack Previews").GetComponentsInChildren<Animator>()){if(live.transform.parent.name.Contains("Skill_03"))continue;var root=UnityEngine.Object.Instantiate(live.transform.parent.gameObject);try{root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;var c=a.runtimeAnimatorController.animationClips[0];var ts=a.GetComponentsInChildren<Transform>();var r=ts.First(t=>t.name=="RightHand");var l=ts.First(t=>t.name=="LeftHand");var s=ts.First(t=>t.name=="Sword");var samples=new List<object>();for(int f=0;f<=Mathf.RoundToInt(c.length*30);f+=3){c.SampleAnimation(a.gameObject,f/30f);samples.Add(new{f,distance=Vector3.Distance(r.position,l.position),left=l.position.ToString("F3"),right=r.position.ToString("F3")});}report.Add(new{name=live.transform.parent.name,swordScale=s.lossyScale.ToString(),swordBounds=s.GetComponent<MeshFilter>().sharedMesh.bounds.ToString(),samples});}finally{UnityEngine.Object.DestroyImmediate(root);}}System.IO.File.WriteAllText("Assets/3DBattle/Authoring~/AttackHandInspection.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;}
}
